from taf.nms.nom.auth.authorization import TokenManager
from taf.nms.nom.interfaces.nom_v1 import NOMv1

try:
    from urllib.parse import urlparse
except ImportError:
    from urlparse import urlparse


class NomVersionNotSupported(Exception):
    """ Raises when provided NOM version is not supported. """


class ConnectionDetails(object):
    def __init__(self, apigw_uri, port, username, password, secure=True):
        self.protocol = 'https://' if secure else 'http://'
        parsed_url = self._parse_url(apigw_uri)
        self.host = parsed_url.hostname
        self.port = port
        self.path = parsed_url.path
        self.username = username
        self.password = password

        self.base_url = '{protocol}{host}:{port}{path}'.format(protocol=self.protocol,
                                                               host=self.host,
                                                               port=self.port,
                                                               path=self.path)

    @staticmethod
    def _parse_url(url):
        if url.startswith('http'):
            return urlparse(url)
        else:
            return urlparse('https://{url}'.format(url=url))


class SupportedNOMs(object):
    nom_v1 = NOMv1


class NOMProvider(object):
    @classmethod
    def create_nom(cls, client_id, client_secret, user_mgmt_uri, apigw_uri, port, username, password, nom_version,
                   secure):
        nom_type = getattr(SupportedNOMs, nom_version, None)

        if not nom_type:
            exception_message = 'Version {} of nom is not supported'.format(nom_version)
            raise NomVersionNotSupported(exception_message)

        token = TokenManager(client_id, client_secret, username, password, user_mgmt_uri)
        con_details = ConnectionDetails(apigw_uri, port, username, password, secure)
        nom = nom_type(con_details, token)

        return nom
